-- New provisioned database inspected: no public tables/functions, no auth users or buckets.
-- The legacy supabase/schema.sql is retained as historical reference, not applied.
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT '' CHECK(length(name)<=100), phone text NOT NULL DEFAULT '' CHECK(length(phone)<=30), location text NOT NULL DEFAULT '' CHECK(length(location)<=500), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO authenticated;
GRANT UPDATE(name,phone,location) ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL DEFAULT 'buyer' CHECK(role IN ('buyer','supplier','admin')));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin') $$;
REVOKE ALL ON FUNCTION public.is_admin() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_admin() TO authenticated, anon;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_admin());
CREATE POLICY own_profile ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.is_admin());
CREATE POLICY update_profile ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.pilot_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ BEGIN
 INSERT INTO public.profiles(id,name) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'name',''),100));
 INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'buyer'); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.pilot_new_user() FROM PUBLIC;
CREATE TRIGGER pilot_auth_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.pilot_new_user();
CREATE TABLE public.supplier_businesses (id uuid PRIMARY KEY REFERENCES public.profiles(id), business_name text NOT NULL CHECK(length(trim(business_name)) BETWEEN 2 AND 150), location text NOT NULL CHECK(length(trim(location)) BETWEEN 2 AND 500), verification_status text NOT NULL DEFAULT 'pending' CHECK(verification_status IN ('pending','approved','rejected')), verification_notes text NOT NULL DEFAULT '' CHECK(length(verification_notes)<=1000), reviewed_by uuid, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.supplier_businesses TO authenticated;
GRANT ALL ON public.supplier_businesses TO service_role;
ALTER TABLE public.supplier_businesses ENABLE ROW LEVEL SECURITY;
CREATE POLICY business_private ON public.supplier_businesses FOR SELECT TO authenticated USING(id=auth.uid() OR public.is_admin());
CREATE FUNCTION public.supplier_approved(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$ SELECT EXISTS(SELECT 1 FROM public.supplier_businesses b JOIN public.user_roles r ON r.user_id=b.id WHERE b.id=_id AND b.verification_status='approved' AND r.role='supplier') $$;
REVOKE ALL ON FUNCTION public.supplier_approved(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.supplier_approved(uuid) TO anon,authenticated;
CREATE FUNCTION public.register_supplier(_name text,_location text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ BEGIN
 IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role IN ('buyer','supplier')) THEN RAISE EXCEPTION 'Not allowed'; END IF;
 IF length(trim(_name)) NOT BETWEEN 2 AND 150 OR length(trim(_location)) NOT BETWEEN 2 AND 500 OR _name IS NULL OR _location IS NULL THEN RAISE EXCEPTION 'Invalid business information'; END IF;
 INSERT INTO public.supplier_businesses(id,business_name,location) VALUES(auth.uid(),trim(_name),trim(_location)) ON CONFLICT(id) DO NOTHING;
 UPDATE public.user_roles SET role='supplier' WHERE user_id=auth.uid() AND role='buyer'; END $$;
CREATE FUNCTION public.review_supplier(_id uuid,_status text,_notes text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ BEGIN
 IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin only'; END IF;
 IF _status IS NULL OR _status NOT IN ('approved','rejected') OR length(coalesce(_notes,''))>1000 THEN RAISE EXCEPTION 'Invalid review'; END IF;
 UPDATE public.supplier_businesses SET verification_status=_status,verification_notes=coalesce(_notes,''),reviewed_by=auth.uid(),reviewed_at=now() WHERE id=_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Supplier not found'; END IF; END $$;
CREATE TABLE public.categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE CHECK(length(name) BETWEEN 1 AND 100),description text);
GRANT SELECT ON public.categories TO anon,authenticated;
GRANT ALL ON public.categories TO service_role;
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY category_public ON public.categories FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),supplier_id uuid NOT NULL REFERENCES public.supplier_businesses(id),category_id uuid REFERENCES public.categories(id),name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 150),description text CHECK(length(description)<=3000),price numeric(12,2) NOT NULL CHECK(price>0),unit text NOT NULL CHECK(length(trim(unit)) BETWEEN 1 AND 30),stock integer NOT NULL DEFAULT 0 CHECK(stock>=0),image_url text CHECK(image_url IS NULL OR (length(image_url)<=2000 AND image_url ~ '^https://')),location text CHECK(length(location)<=500),is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.products TO anon,authenticated;
GRANT INSERT,UPDATE ON public.products TO authenticated;
GRANT ALL ON public.products TO service_role;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY product_public ON public.products FOR SELECT TO anon,authenticated USING(is_active AND public.supplier_approved(supplier_id));
CREATE POLICY product_owner_read ON public.products FOR SELECT TO authenticated USING(supplier_id=auth.uid() OR public.is_admin());
CREATE POLICY product_insert ON public.products FOR INSERT TO authenticated WITH CHECK(supplier_id=auth.uid() AND public.supplier_approved(auth.uid()));
CREATE POLICY product_update ON public.products FOR UPDATE TO authenticated USING(supplier_id=auth.uid() AND public.supplier_approved(auth.uid())) WITH CHECK(supplier_id=auth.uid() AND public.supplier_approved(auth.uid()));
CREATE TABLE public.quote_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),buyer_id uuid NOT NULL REFERENCES public.profiles(id),supplier_id uuid NOT NULL REFERENCES public.supplier_businesses(id),product_id uuid NOT NULL REFERENCES public.products(id),product_name text NOT NULL,unit text NOT NULL,quantity integer NOT NULL CHECK(quantity>0 AND quantity<=1000000),delivery_address text NOT NULL CHECK(length(trim(delivery_address)) BETWEEN 3 AND 500),phone text NOT NULL CHECK(length(phone) BETWEEN 5 AND 30),notes text NOT NULL DEFAULT '' CHECK(length(notes)<=2000),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','responded','accepted','rejected')),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.quote_requests TO authenticated;
GRANT ALL ON public.quote_requests TO service_role;
ALTER TABLE public.quote_requests ENABLE ROW LEVEL SECURITY;
CREATE INDEX quote_buyer_idx ON public.quote_requests(buyer_id,created_at DESC);
CREATE INDEX quote_supplier_idx ON public.quote_requests(supplier_id,created_at DESC);
CREATE POLICY quote_participants ON public.quote_requests FOR SELECT TO authenticated USING(buyer_id=auth.uid() OR supplier_id=auth.uid() OR public.is_admin());
CREATE TABLE public.quote_responses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_id uuid NOT NULL UNIQUE REFERENCES public.quote_requests(id),unit_price numeric(12,2) NOT NULL CHECK(unit_price>0),delivery_fee numeric(12,2) NOT NULL DEFAULT 0 CHECK(delivery_fee>=0),expires_at timestamptz NOT NULL,notes text NOT NULL DEFAULT '' CHECK(length(notes)<=2000),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.quote_responses TO authenticated;
GRANT ALL ON public.quote_responses TO service_role;
ALTER TABLE public.quote_responses ENABLE ROW LEVEL SECURITY;
CREATE POLICY response_participants ON public.quote_responses FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.quote_requests q WHERE q.id=request_id AND (q.buyer_id=auth.uid() OR q.supplier_id=auth.uid() OR public.is_admin())));
CREATE TABLE public.orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_id uuid NOT NULL UNIQUE REFERENCES public.quote_requests(id),buyer_id uuid NOT NULL REFERENCES public.profiles(id),supplier_id uuid NOT NULL REFERENCES public.supplier_businesses(id),product_name text NOT NULL,unit text NOT NULL,quantity integer NOT NULL,unit_price numeric(12,2) NOT NULL,delivery_fee numeric(12,2) NOT NULL,total numeric(18,2) NOT NULL CHECK(total>0),delivery_address text NOT NULL,phone text NOT NULL,notes text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'confirmed' CHECK(status='confirmed'),payment_status text NOT NULL DEFAULT 'unpaid' CHECK(payment_status='unpaid'),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.orders TO authenticated;
GRANT ALL ON public.orders TO service_role;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
CREATE INDEX orders_buyer_idx ON public.orders(buyer_id);
CREATE INDEX orders_supplier_idx ON public.orders(supplier_id);
CREATE POLICY order_participants ON public.orders FOR SELECT TO authenticated USING(buyer_id=auth.uid() OR supplier_id=auth.uid() OR public.is_admin());
CREATE FUNCTION public.request_quote(_product_id uuid,_quantity integer,_address text,_phone text,_notes text DEFAULT '') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ DECLARE p public.products; result uuid; BEGIN
 IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='buyer') THEN RAISE EXCEPTION 'Buyer account required'; END IF;
 IF _quantity IS NULL OR _quantity NOT BETWEEN 1 AND 1000000 OR _address IS NULL OR length(trim(_address)) NOT BETWEEN 3 AND 500 OR _phone IS NULL OR length(trim(_phone)) NOT BETWEEN 5 AND 30 OR length(coalesce(_notes,''))>2000 THEN RAISE EXCEPTION 'Invalid quote request'; END IF;
 SELECT * INTO p FROM public.products WHERE id=_product_id AND is_active FOR SHARE;
 IF p.id IS NULL OR NOT public.supplier_approved(p.supplier_id) THEN RAISE EXCEPTION 'Material unavailable'; END IF;
 INSERT INTO public.quote_requests(buyer_id,supplier_id,product_id,product_name,unit,quantity,delivery_address,phone,notes) VALUES(auth.uid(),p.supplier_id,p.id,p.name,p.unit,_quantity,trim(_address),trim(_phone),coalesce(_notes,'')) RETURNING id INTO result; RETURN result; END $$;
CREATE FUNCTION public.respond_quote(_request_id uuid,_price numeric,_delivery_fee numeric,_expires_at timestamptz,_notes text DEFAULT '') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ DECLARE q public.quote_requests; result uuid; BEGIN
 SELECT * INTO q FROM public.quote_requests WHERE id=_request_id FOR UPDATE;
 IF q.id IS NULL OR q.supplier_id IS DISTINCT FROM auth.uid() OR NOT public.supplier_approved(auth.uid()) THEN RAISE EXCEPTION 'Approved supplier required'; END IF;
 IF q.status<>'pending' THEN RAISE EXCEPTION 'Request already answered'; END IF;
 IF _price IS NULL OR _price<=0 OR _price>9999999999.99 OR _price<>round(_price,2) OR _delivery_fee IS NULL OR _delivery_fee<0 OR _delivery_fee>9999999999.99 OR _delivery_fee<>round(_delivery_fee,2) OR _expires_at IS NULL OR _expires_at<=now() OR _expires_at>now()+interval '90 days' OR length(coalesce(_notes,''))>2000 THEN RAISE EXCEPTION 'Invalid price or expiry'; END IF;
 INSERT INTO public.quote_responses(request_id,unit_price,delivery_fee,expires_at,notes) VALUES(q.id,_price,_delivery_fee,_expires_at,coalesce(_notes,'')) RETURNING id INTO result;
 UPDATE public.quote_requests SET status='responded' WHERE id=q.id; RETURN result; END $$;
CREATE FUNCTION public.decide_quote(_request_id uuid,_accept boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ DECLARE q public.quote_requests; r public.quote_responses; p public.products; result uuid; BEGIN
 SELECT * INTO q FROM public.quote_requests WHERE id=_request_id FOR UPDATE;
 IF q.id IS NULL OR q.buyer_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Request owner required'; END IF;
 IF _accept IS NULL THEN RAISE EXCEPTION 'Decision required'; END IF;
 IF q.status='accepted' AND _accept THEN SELECT id INTO result FROM public.orders WHERE request_id=q.id; RETURN result; END IF;
 IF q.status<>'responded' THEN RAISE EXCEPTION 'Quote is not awaiting a decision'; END IF;
 IF NOT _accept THEN UPDATE public.quote_requests SET status='rejected' WHERE id=q.id; RETURN NULL; END IF;
 SELECT * INTO r FROM public.quote_responses WHERE request_id=q.id;
 IF r.id IS NULL OR r.expires_at<=now() OR NOT public.supplier_approved(q.supplier_id) THEN RAISE EXCEPTION 'Quote expired or supplier unavailable'; END IF;
 SELECT * INTO p FROM public.products WHERE id=q.product_id FOR UPDATE;
 IF p.id IS NULL OR NOT p.is_active OR p.stock<q.quantity THEN RAISE EXCEPTION 'Insufficient available stock'; END IF;
 INSERT INTO public.orders(request_id,buyer_id,supplier_id,product_name,unit,quantity,unit_price,delivery_fee,total,delivery_address,phone,notes) VALUES(q.id,q.buyer_id,q.supplier_id,q.product_name,q.unit,q.quantity,r.unit_price,r.delivery_fee,round(q.quantity*r.unit_price+r.delivery_fee,2),q.delivery_address,q.phone,q.notes) RETURNING id INTO result;
 UPDATE public.products SET stock=stock-q.quantity WHERE id=p.id;
 UPDATE public.quote_requests SET status='accepted' WHERE id=q.id; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.register_supplier(text,text),public.review_supplier(uuid,text,text),public.request_quote(uuid,integer,text,text,text),public.respond_quote(uuid,numeric,numeric,timestamptz,text),public.decide_quote(uuid,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.register_supplier(text,text),public.review_supplier(uuid,text,text),public.request_quote(uuid,integer,text,text,text),public.respond_quote(uuid,numeric,numeric,timestamptz,text),public.decide_quote(uuid,boolean) TO authenticated;
